<?php
require_once __DIR__.'/../config/config.php';
requireRole(['Administrator','Editor','Viewer','Guest']); require_once __DIR__.'/../app/layout.php';$pdo=db();$year=(int)($_GET['year']??date('Y'));$q=trim($_GET['q']??'');
$sql='SELECT p.fiscal_year, TRIM(LOWER(p.item_name)) item_key, MIN(p.item_name) item_name, p.unit, c.name category, SUM(p.quantity) total_qty, SUM(p.quantity*p.unit_price) total_abc, CASE WHEN SUM(p.quantity)=0 THEN 0 ELSE SUM(p.quantity*p.unit_price)/SUM(p.quantity) END avg_price, COUNT(DISTINCT p.area_id) area_count, GROUP_CONCAT(DISTINCT a.name ORDER BY a.name SEPARATOR ", ") areas FROM ppmp_items p JOIN areas a ON a.id=p.area_id JOIN categories c ON c.id=p.category_id WHERE p.fiscal_year=?';$args=[$year];if($q!==''){$sql.=' AND (p.item_name LIKE ? OR c.name LIKE ? OR a.name LIKE ?)';$args=[...$args,"%$q%","%$q%","%$q%"];}$sql.=' GROUP BY p.fiscal_year, TRIM(LOWER(p.item_name)), p.unit, c.id, c.name ORDER BY item_name';$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll();$grandQty=0;$grandAbc=0;foreach($rows as $r){$grandQty+=(float)$r['total_qty'];$grandAbc+=(float)$r['total_abc'];}pageStart('Consolidated Annual Procurement Plan');
?><div class="panel"><div class="toolbar"><form><input class="input" name="q" placeholder="Search consolidated APP" value="<?=e($q)?>"><input type="hidden" name="year" value="<?=$year?>"></form><span class="badge"><?=count($rows)?> consolidated lines</span><span class="badge">ABC: ₱<?=number_format($grandAbc,2)?></span></div><p style="font-size:12px;color:#6b7280">Equivalent items are consolidated across all Area/Unit PPMPs using normalized item name + unit + category. Source quantities are summed; total ABC is summed; displayed unit price is weighted average.</p><div class="table-wrap"><table class="table"><tr><th>Item</th><th>Category</th><th>Unit</th><th>Consolidated Qty</th><th>Weighted Unit Price</th><th>Total ABC</th><th>Contributing Areas/Units</th></tr><?php foreach($rows as $r):?><tr><td><b><?=e($r['item_name'])?></b></td><td><?=e($r['category'])?></td><td><?=e($r['unit'])?></td><td><?=number_format($r['total_qty'],2)?></td><td>₱<?=number_format($r['avg_price'],2)?></td><td><b>₱<?=number_format($r['total_abc'],2)?></b></td><td><?=e($r['areas'])?> <small>(<?=$r['area_count']?>)</small></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="empty">No PPMP data for FY <?=$year?>.</td></tr><?php endif;?></table></div></div><?php pageEnd();
